export async function digest(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('')}
let db;
export function openDB(){if(db)return Promise.resolve(db);return new Promise((resolve,reject)=>{const req=indexedDB.open('verse-one-2',1);req.onupgradeneeded=()=>req.result.createObjectStore('packs',{keyPath:'id'});req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('Close other VERSE ONE tabs and retry.'));req.onsuccess=()=>{db=req.result;resolve(db)}})}
export async function getPack(id){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('packs','readonly'),r=tx.objectStore('packs').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
export async function putPack(item){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('packs','readwrite');tx.objectStore('packs').put(item);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Installation transaction aborted.'))})}
export async function installedIds(){const db=await openDB();return new Promise((resolve,reject)=>{const r=db.transaction('packs','readonly').objectStore('packs').getAllKeys();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
export async function validateBytes(bytes,edition){if(bytes.byteLength!==edition.bytes)throw Error('Pack size mismatch. Installation rejected.');if(await digest(bytes)!==edition.sha256)throw Error('Pack checksum mismatch. Installation rejected.');const p=JSON.parse(new TextDecoder().decode(bytes));if(p.id!==edition.id||p.validation.status!=='source-compared'||p.books.length!==edition.books||!p.index)throw Error('Invalid edition package.');return p}
